-- Upgrade-test fixture: captured schema shape of the optional integration; no market data.
create table if not exists public.catalyst_reports (
  id uuid default gen_random_uuid() not null,
  report_type text not null,
  trading_date_checked date not null,
  generated_at_sgt timestamp with time zone not null,
  coverage_window text,
  market_session_focus text,
  output_version text default 'Catalyst_Table_v2'::text not null,
  market_summary text,
  themes_summary text,
  best_focus text,
  table_1_tickers text[] default '{}'::text[] not null,
  table_2_tickers text[] default '{}'::text[] not null,
  table_3_tickers text[] default '{}'::text[] not null,
  raw_report_text text,
  created_at timestamp with time zone default now() not null,
  constraint catalyst_reports_output_version_check CHECK ((output_version = 'Catalyst_Table_v2'::text)),
  constraint catalyst_reports_pkey PRIMARY KEY (id),
  constraint catalyst_reports_report_type_check CHECK ((report_type = ANY (ARRAY['Premarket Catalyst Brief'::text, 'After-Market Catalyst Brief'::text, 'Weekend Catalyst Summary'::text]))),
  constraint catalyst_reports_report_type_trading_date_checked_generated_key UNIQUE (report_type, trading_date_checked, generated_at_sgt)
);
alter table public.catalyst_reports enable row level security;
create table if not exists public.catalyst_rows (
  id bigint generated by default as identity not null,
  report_id uuid not null,
  table_number smallint not null,
  row_order integer not null,
  ticker text not null,
  catalyst_event_date text not null,
  catalyst_quality_direction text not null,
  primary_catalyst_category text not null,
  catalyst_tags text not null,
  catalyst_summary text not null,
  sector text not null,
  theme text not null,
  direct_sympathy_sector_move text not null,
  sympathy_related_tickers text not null,
  catalyst_release_session text not null,
  reaction_date text not null,
  move_already_done text not null,
  volume_liquidity_confirmation text not null,
  freshness_catalyst_age text not null,
  source_confidence text not null,
  primary_source_evidence text not null,
  trade_read text not null,
  risk_invalidator text not null,
  action_priority text not null,
  trading_date_checked date not null,
  created_at timestamp with time zone default now() not null,
  constraint catalyst_rows_action_priority_check CHECK ((action_priority = ANY (ARRAY['High-Conviction Watch'::text, 'Starter Watch'::text, 'Watch'::text, 'Avoid Chase'::text, 'Avoid'::text, 'Short Watch'::text, 'Avoid Short'::text]))),
  constraint catalyst_rows_catalyst_quality_direction_check CHECK ((catalyst_quality_direction = ANY (ARRAY['A+ Bullish'::text, 'A Bullish'::text, 'B Bullish'::text, 'N / Neutral'::text, 'A+ Bearish'::text, 'A Bearish'::text, 'B Bearish'::text, 'Sympathy / Continuation'::text, 'No Fresh Catalyst'::text]))),
  constraint catalyst_rows_catalyst_release_session_check CHECK ((catalyst_release_session = ANY (ARRAY['Premarket'::text, 'Regular Market Hours'::text, 'After Close'::text, 'Overnight'::text, 'Weekend / Holiday'::text, 'Needs Verification'::text]))),
  constraint catalyst_rows_direct_sympathy_sector_move_check CHECK ((direct_sympathy_sector_move = ANY (ARRAY['Direct'::text, 'Sympathy'::text, 'Sector Move'::text, 'Mixed'::text, 'None'::text]))),
  constraint catalyst_rows_pkey PRIMARY KEY (id),
  constraint catalyst_rows_primary_catalyst_category_check CHECK ((primary_catalyst_category = ANY (ARRAY['Earnings'::text, 'Guidance / Business Update'::text, 'Clinical Data'::text, 'FDA / Regulatory'::text, 'M&A / Strategic Transaction'::text, 'Contract / Orders'::text, 'Analyst Action'::text, 'Capital Markets / Financing'::text, 'Corporate Action'::text, 'Legal / Accounting'::text, 'Product / Commercial'::text, 'Macro / Policy'::text, 'Sector / Sympathy'::text, 'Scheduled Event'::text, 'No Fresh Catalyst'::text]))),
  constraint catalyst_rows_report_id_fkey FOREIGN KEY (report_id) REFERENCES catalyst_reports(id) ON DELETE CASCADE,
  constraint catalyst_rows_report_id_table_number_row_order_key UNIQUE (report_id, table_number, row_order),
  constraint catalyst_rows_row_order_check CHECK ((row_order > 0)),
  constraint catalyst_rows_sector_check CHECK ((sector = ANY (ARRAY['Technology'::text, 'Healthcare'::text, 'Consumer Discretionary'::text, 'Consumer Staples'::text, 'Industrials'::text, 'Energy'::text, 'Financials'::text, 'Communication Services'::text, 'Materials'::text, 'Utilities'::text, 'Real Estate'::text, 'Crypto / Digital Assets'::text, 'ETF / Index'::text, 'Other'::text]))),
  constraint catalyst_rows_source_confidence_check CHECK ((source_confidence = ANY (ARRAY['High'::text, 'Medium'::text, 'Low'::text]))),
  constraint catalyst_rows_table_grade_check CHECK ((((table_number = 1) AND (catalyst_quality_direction = ANY (ARRAY['A+ Bullish'::text, 'A Bullish'::text]))) OR ((table_number = 2) AND (catalyst_quality_direction = ANY (ARRAY['A+ Bearish'::text, 'A Bearish'::text]))) OR (table_number = 3))),
  constraint catalyst_rows_table_number_check CHECK ((table_number = ANY (ARRAY[1, 2, 3])))
);
alter table public.catalyst_rows enable row level security;
